module pulse_detect(
    input clk, rst_n, data_in,
    output reg data_out
);
// TODO: Please add your solution here
reg [1:0] state, next_state;
parameter S0 = 2'b00;
parameter S1 = 2'b01;
parameter S2 = 2'b10;
parameter S3 = 2'b11;
always@(*) begin
	case(state)
		S0: begin
			if(data_in == 1'b1) begin
				next_state = S1;
			end else begin
				next_state = S0;
			end
		end

		S1: begin
			if(data_in == 1'b1) begin
				next_state = S2;
			end else begin
				next_state = S1;
			end
		end

		S2: begin
			if(data_in == 1'b0) begin
				next_state = S3;
			end else begin
				next_state = S1;
			end
		end

		S3: begin
			if(data_in == 1'b0) begin
				next_state = S0;
			end else begin
				next_state = S1;
			end
		end

		default: next_state = S0;
	endcase
end
always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		state <= S0;
		data_out <= 1'b0;
	end else begin
		state <= next_state;

		if((next_state == S3) && !data_in) begin
			data_out <= 1'b1;
		end else begin
			data_out <= 1'b0;
		end
	end
end
endmodule
